// Finding aids (round 3): one short guide per collection (class of the classification) and per pass, the special
// collection of Dinis's guidance with his words verbatim, and the front door (index.md). READING-ROOM.md's limits hold:
// a table never has more than 25 rows, a page is about 150 lines (a long list is split into parts), no em-dash, every
// library word glossed in plain words on first use, dates in words and UTC.
// Generated by the library generator; the scope notes of the classes are a hand file (finding-aids/scope-notes.json).
import path from 'node:path'
import { readJson, cmp, dateWords, mdCell, noDash, words, GENERATOR } from './util.mjs'
import { cardUrl } from './cards.mjs'
import { ROWS_PER_TABLE } from './shelf.mjs'

export const ROOM = 'reading-room.htm'
const short = (n) => (n ? String(n).replace(/@PrompTugal\.dinis$/, '@') : '')
const callOf = (c) => c.call.split(' ')[0]
const classOf = (c) => callOf(c).split('.')[0]
const link = (c) => { const u = cardUrl(c); return u ? `[${mdCell(c.title)}](${u})` : mdCell(c.title) }

function front(ctx, title, extra = '') {
  return ['---', `title: ${JSON.stringify(title)}`, 'by: librarian@PrompTugal.dinis',
    `generated: ${JSON.stringify('by ' + GENERATOR + ' from board/catalogue.json as generated ' + (ctx.catalogue.generated || 'unknown'))}`,
    `site_version: ${JSON.stringify(ctx.catalogue.site_version || '')}`, 'source: board/catalogue.json', ...(extra ? [extra] : []), '---', ''].join('\n')
}
function chunks(rows, head, n = ROWS_PER_TABLE) {
  const out = []
  for (let i = 0; i < rows.length; i += n) {
    if (i) out.push('', `(continued, rows ${i + 1} to ${Math.min(i + n, rows.length)})`, '')
    out.push(head[0], head[1], ...rows.slice(i, i + n))
  }
  return out
}

// how connected a card is, by the links that say something (not who made it or what it is about)
function strengths(cards) {
  const m = new Map()
  for (const c of cards) for (const l of c.links || []) {
    if (['about', 'made_by', 'part_of', 'includes'].includes(l.rel)) continue
    m.set(c.id, (m.get(c.id) || 0) + 1)
    if (!l.to.includes(':') || l.to.startsWith('auth:') || l.to.startsWith('subj:')) continue
    m.set(l.to, (m.get(l.to) || 0) + 1)
  }
  return m
}
const best = (list, str, n) => [...list].sort((a, b) => (str.get(b.id) || 0) - (str.get(a.id) || 0) || cmp(a.call, b.call)).slice(0, n)

const GLOSS = 'A **finding aid** (a short guide to one collection: what is in it and where to start) and a **card** (one entry: what a thing is, where it is, who made it) are the library\'s two words here.'

export function buildAids(ctx, cards) {
  const files = {}
  const cls = ctx.classification.classes
  const notes = readJson(path.join(ctx.libDir, 'finding-aids/scope-notes.json'), { classes: {} }).classes
  const live = cards.filter((c) => c.status !== 'withdrawn')
  const str = strengths(cards)
  const byClass = new Map()
  for (const c of cards) { const k = classOf(c); if (!byClass.has(k)) byClass.set(k, []); byClass.get(k).push(c) }
  const shelfPage = (k) => { const n = Math.ceil(byClass.get(k).length / 100); return n === 1 ? [`../shelf-list/${k}.md`] : Array.from({ length: n }, (_, i) => `../shelf-list/${k}-${i + 1}.md`) }

  // cross links between classes (for "see also")
  const classOfId = new Map(cards.map((c) => [c.id, classOf(c)]))
  const cross = new Map()
  for (const c of cards) for (const l of c.links || []) {
    if (['about', 'made_by'].includes(l.rel)) continue
    const t = classOfId.get(l.to)
    if (!t || t === classOf(c)) continue
    const k = classOf(c)
    if (!cross.has(k)) cross.set(k, new Map())
    cross.get(k).set(t, (cross.get(k).get(t) || 0) + 1)
  }

  const classKeys = [...byClass.keys()].sort(cmp)
  for (const k of classKeys) {
    const list = byClass.get(k)
    const cl = cls[k] || { name: k, subs: {} }
    const note = notes[k] || {}
    const makers = new Map()
    for (const c of list) if (c.provenance.made && c.provenance.made.by) makers.set(c.provenance.made.by, (makers.get(c.provenance.made.by) || 0) + 1)
    const keepers = note.kept_by || [...makers].sort((a, b) => b[1] - a[1] || cmp(a[0], b[0])).slice(0, 2).map(([m]) => short(m)).join(' and ')
    const subs = new Map()
    for (const c of list) { const s = callOf(c).split('.')[1]; if (!subs.has(s)) subs.set(s, []); subs.get(s).push(c) }
    const out = [front(ctx, `Finding aid: ${cl.name}`)]
    out.push(`# ${cl.name} (${list.length} cards)`, '')
    out.push(`${note.scope || `The cards of class ${k}.`} Kept by ${keepers}.`, '')
    out.push(`(Plain words: ${GLOSS})`, '')
    out.push('## Start here', '')
    for (const c of best(live.filter((x) => classOf(x) === k), str, 3)) out.push(`- ${link(c)} (\`${c.call}\`): ${mdCell(words(c.what || c.title, 25))}`)
    out.push('', '## How it is arranged', '')
    out.push(`${note.arranged || 'By call number: the subclass, then the thing\'s own short name.'} There ${subs.size === 1 ? 'is 1 subclass' : `are ${subs.size} subclasses`}, each a container below.`, '')
    out.push('## The container list', '')
    const rows = [...subs.keys()].sort(cmp).map((s) => {
      const l = subs.get(s)
      const eg = best(l.filter((c) => c.status !== 'withdrawn'), str, 2).map((c) => link(c)).join(', ')
      return `| \`${k}.${s}\` | ${mdCell(cl.subs[s] || s)} | ${l.length} | ${eg} |`
    })
    out.push(...chunks(rows, ['| Container | What it holds | Cards | Cards worth opening |', '|---|---|---|---|']), '')
    out.push('## Every card', '')
    out.push(`The shelf list (the cards in call-number order, 25 to a table): ${shelfPage(k).map((p, i, a) => `[${a.length > 1 ? 'part ' + (i + 1) : 'open'}](${p})`).join(', ')}.`, '')
    const sp = list.filter((c) => c.special)
    if (sp.length) out.push(`Special collection: ${[...new Set(sp.map((c) => c.special))].sort(cmp).join(', ')} (${sp.length} cards). Dinis's guidance has its own guide: [guidance](../special/guidance.md).`, '')
    out.push('## See also', '')
    const see = [...(cross.get(k) || [])].sort((a, b) => b[1] - a[1] || cmp(a[0], b[0])).slice(0, 3)
    out.push(see.length ? see.map(([t, n]) => `- [${mdCell((cls[t] || { name: t }).name)}](${t}.md) (${n} connections from this collection)`).join('\n') : '- [All finding aids](index.md)')
    out.push(`- [The reading room](../reading-room.htm): search the cards and draw the library graph`, '')
    out.push('Back to the front door: [the library](../index.md)', '')
    files[`finding-aids/${k}.md`] = out.join('\n')
  }

  // ---- passes
  const passes = live.filter((c) => c.type === 'pass').sort((a, b) => cmp(a.id, b.id))
  const findingsOf = new Map()
  for (const c of live) if (c.type === 'finding') {
    const p = (c.links || []).find((l) => l.rel === 'part_of' && l.to.startsWith('pass:'))
    if (p) { if (!findingsOf.has(p.to)) findingsOf.set(p.to, []); findingsOf.get(p.to).push(c) }
  }
  const byId = new Map(cards.map((c) => [c.id, c]))
  for (const p of passes) {
    const slug = p.id.slice(p.id.indexOf(':') + 1)
    const f = (findingsOf.get(p.id) || []).sort((a, b) => Number(a.id.split('#')[1]) - Number(b.id.split('#')[1]))
    const fa = p.facts || {}
    const out = [front(ctx, `Finding aid: pass ${slug}`)]
    out.push(`# Pass: ${mdCell(slug)}`, '')
    out.push(`${mdCell(words(p.what || p.title, 40))}`, '')
    const meta = [fa.state ? `state ${fa.state}` : null, fa.opened ? `opened ${dateWords(fa.opened)}` : null, fa.owner ? `owner ${short(fa.owner)}` : null, `${f.length} findings`].filter(Boolean)
    out.push(`Scope note: a **pass** is a focused round of work on one thing, in a fixed order and within a budget. This one: ${meta.join(', ')}. The pass file: ${link(p)}.`, '')
    out.push('## The container list: the findings', '')
    if (f.length) {
      const rows = f.map((c) => `| ${c.id.split('#')[1]} | ${link(c)} | ${mdCell(short((c.facts || {}).owner || ''))} | ${mdCell((c.facts || {}).decision || ((c.facts || {}).decided === false ? 'open' : ''))} |`)
      out.push(...chunks(rows, ['| No. | Finding | Owner | Decision |', '|---|---|---|---|']))
    } else out.push('No findings are logged in this pass yet.')
    out.push('')
    const cites = (p.links || []).filter((l) => l.rel === 'cites' && byId.has(l.to)).map((l) => byId.get(l.to))
    out.push('## Cards this pass names', '')
    out.push(cites.length ? cites.slice(0, 10).map((c) => `- ${link(c)} (\`${c.call}\`)`).join('\n') : 'None found in the pass file.')
    if (cites.length > 10) out.push(`(${cites.length - 10} more in the card.)`)
    out.push('', '## See also', '')
    const also = (p.links || []).filter((l) => l.rel === 'see_also' && byId.has(l.to)).map((l) => byId.get(l.to)).slice(0, 3)
    for (const c of also) out.push(`- [${mdCell(c.title)}](${c.type === 'pass' ? `${c.id.slice(c.id.indexOf(':') + 1)}.md` : cardUrl(c)})`)
    out.push('- [All passes](../index.md)', '- [The reading room](../../reading-room.htm)', '')
    out.push('Back to the front door: [the library](../../index.md)', '')
    files[`finding-aids/passes/${slug}.md`] = out.join('\n')
  }
  // the index of the aids
  {
    const out = [front(ctx, 'The finding aids of the library')]
    out.push('# The finding aids', '')
    out.push(`${GLOSS} One aid for each collection (class), one for each pass, and the special collection of Dinis's guidance.`, '')
    out.push('## Collections', '')
    out.push(...chunks(classKeys.map((k) => `| [${mdCell((cls[k] || { name: k }).name)}](${k}.md) | \`${k}\` | ${byClass.get(k).length} |`), ['| Collection | Class | Cards |', '|---|---|---|']), '')
    out.push('## Passes', '')
    out.push(...chunks(passes.map((p) => { const slug = p.id.slice(p.id.indexOf(':') + 1); return `| [${mdCell(slug)}](passes/${slug}.md) | ${mdCell((p.facts || {}).state || '')} | ${(findingsOf.get(p.id) || []).length} |` }), ['| Pass | State | Findings |', '|---|---|---|']), '')
    out.push('## Special', '', '- [Dinis\'s guidance, his words, by theme](../special/guidance.md)', '')
    out.push('Back to the front door: [the library](../index.md)', '')
    files['finding-aids/index.md'] = out.join('\n')
  }
  return { files, passes: passes.length, classes: classKeys.length }
}

// ---------------------------------------------------------------- the special collection of Dinis's guidance
const themeNo = (t) => { const m = /^(\d+)\./.exec(t || ''); return m ? Number(m[1]) : 999 }
const PER_PART = 50

export function buildGuidance(ctx, cards) {
  const files = {}
  const ideas = cards.filter((c) => c.type === 'idea' && c.status !== 'withdrawn')
  const questions = cards.filter((c) => c.type === 'question' && c.status !== 'withdrawn')
  const isLater = (c) => !!(c.facts && (c.facts.later === true || /^later/.test(String(c.facts.when || ''))))
  const state = (c) => {
    const f = c.facts || {}
    const bits = [f.when ? String(f.when) : 'no timing given']
    if (f.later === true) bits.push('flagged Later')
    if (f.not_captured === true) bits.push('not captured')
    return bits.join(', ')
  }
  const idOf = (c) => c.id.slice(c.id.indexOf(':') + 1)
  const order = (a, b) => themeNo((a.facts || {}).theme) - themeNo((b.facts || {}).theme) || cmp(a.call, b.call)
  const entry = (c) => {
    const f = c.facts || {}
    const w = c.words ? noDash(c.words) : `(no verbatim words recorded; the ledger's line: ${mdCell(c.title)})`
    const cap = f.captured_in ? `Captured in ${mdCell(f.captured_in)}.` : 'Captured nowhere yet.'
    return [`- **${idOf(c)}**: ${state(c)}; owner ${mdCell(f.owner || 'none named')}; memo ${mdCell(f.memo || 'none')}. ${cap} [card](${cardUrl(c) || '#'})`, `  > ${w.replace(/\s+/g, ' ')}`]
  }
  const later = ideas.filter(isLater).sort(order)
  const rest = ideas.filter((c) => !isLater(c)).sort(order)
  const parts = []
  const addParts = (list, name, withTheme) => {
    for (let i = 0; i < list.length; i += PER_PART) {
      const slice = list.slice(i, i + PER_PART)
      parts.push({ name, slice, themes: [...new Set(slice.map((c) => (c.facts || {}).theme || 'no theme'))] })
    }
  }
  addParts(later, 'later')
  addParts(rest, 'theme')
  const fileOf = (i) => `guidance-${i + 1}.md`
  parts.forEach((p, i) => {
    const out = [front(ctx, `Dinis's guidance, part ${i + 1} of ${parts.length}`, 'special: S1')]
    out.push(`# Dinis's guidance, part ${i + 1} of ${parts.length}: ${p.name === 'later' ? 'the Later ones' : 'the rest, by theme'}`, '')
    out.push(`${p.slice.length} ideas. Each line is one idea of the night memos: its number, its state, who owns it, which memo it came from and where it was captured; under it, Dinis's words as the ideas ledger transcribed them. An em-dash is shown as a hyphen, the library's one change.`, '')
    let theme = null
    for (const c of p.slice) {
      const t = (c.facts || {}).theme || 'no theme'
      if (t !== theme) { out.push(`## ${mdCell(t)}`, ''); theme = t }
      out.push(...entry(c))
    }
    out.push('')
    const nav = ['[All of the guidance](guidance.md)']
    if (i > 0) nav.push(`[Previous part](${fileOf(i - 1)})`)
    if (i < parts.length - 1) nav.push(`[Next part](${fileOf(i + 1)})`)
    out.push(nav.join(' | '), '', 'Back to the front door: [the library](../index.md)', '')
    files[`special/${fileOf(i)}`] = out.join('\n')
  })
  // the guide itself
  const out = [front(ctx, "Dinis's guidance: every idea of the night memos", 'special: S1')]
  out.push("# Dinis's guidance", '')
  out.push(`The special collection **S1** (a special collection is kept apart and its words are never edited): every one of the ${ideas.length} ideas of Dinis's night memos of 5 and 6 November 2026, his words verbatim as the ideas ledger transcribed them, with its state and its owner. The Later ones come first: they are the ideas not to act on now but to keep. Source: \`board/guidance/2026-11-06-the-ideas-ledger.md\` (the ledger) and \`board/guidance/memos/2026-11-06-the-night-memos.md\` (the memos, which win where they differ).`, '')
  out.push(`(Plain words: a **card** is one entry in the library; **Later** is the ledger's own flag for an idea Dinis said to keep for later. ${later.length} ideas are Later or carry a when of later; ${ideas.filter((c) => (c.facts || {}).not_captured === true).length} are not captured anywhere yet.)`, '')
  out.push('## The parts', '')
  const rows = parts.map((p, i) => `| [Part ${i + 1}](${fileOf(i)}) | ${p.name === 'later' ? 'Later ones' : 'by theme'} | ${p.slice.length} | ${mdCell(p.themes.length > 2 ? `${p.themes[0]} to ${p.themes[p.themes.length - 1]}` : p.themes.join('; '))} |`)
  out.push(...chunks(rows, ['| Part | Contents | Ideas | Themes |', '|---|---|---|---|']), '')
  out.push('## The open questions', '')
  out.push(`${questions.length} questions of the ledger that nobody has answered in full. Each is a card:`, '')
  for (const q of questions.sort((a, b) => cmp(a.call, b.call, 'en')).slice(0, 25)) out.push(`- ${link(q)}: ${mdCell(words((q.facts || {}).where_it_stands || q.what, 25))}`)
  out.push('', 'See also: [the guidance on the graph](../reading-room.htm?preset=guidance) (each idea joined to its owner and the file that holds it), [the reality tree](../reality/index.md).', '')
  out.push('Back to the front door: [the library](../index.md)', '')
  files['special/guidance.md'] = out.join('\n')
  return { files, ideas: ideas.length, later: later.length, parts: parts.length, questions: questions.length }
}

// ---------------------------------------------------------------- the front door
export function buildFrontDoor(ctx, cards, extra) {
  const live = cards.filter((c) => c.status !== 'withdrawn')
  const cls = ctx.classification.classes
  const byClass = new Map()
  for (const c of cards) { const k = classOf(c); byClass.set(k, (byClass.get(k) || 0) + 1) }
  const newest = [...live].sort((a, b) => cmp(b.acc, a.acc)).slice(0, 5)
  const out = [front(ctx, 'The library of PrompTugal.news')]
  out.push('# The library of PrompTugal.news', '')
  out.push(`Everything in this repository and on this site in one place: ${live.length} cards, who made each, and when.`, '')
  out.push('Find something: open [the reading room](reading-room.htm) and type the first letters of a title, a call number or a kind. It also draws the library as a graph.', '')
  out.push('Three doors: [Find a page](reading-room.htm) | [What is new](notice-board.md) | [What is waiting](notice-board.md)', '')
  out.push('## New this hour (new accessions: the newest things added)', '')
  for (const c of newest) out.push(`- \`${c.acc}\` ${link(c)}`)
  out.push('', '(All of them: [the accession register](accession-register.jsonl).)', '')
  out.push('## The collections (each has a finding aid, a short guide)', '')
  out.push([...byClass.keys()].sort(cmp).map((k) => `[${mdCell((cls[k] || { name: k }).name)}](finding-aids/${k}.md) (${byClass.get(k)})`).join(' | '), '')
  out.push('Also: [every pass and its findings](finding-aids/index.md) | [Dinis\'s guidance, his words](special/guidance.md) | [the reality tree](reality/index.md) (what exists and what is only proposed) | [the shelf list](shelf-list.md)', '')
  out.push('## Agents: ask here', '')
  out.push('Write one question as a call slip (one question, written down) to the librarian\'s lane; the answer comes in about an hour and is copied to [the register](desk/index.md). What waits on Dinis needs no slip: it is on [the notice board](notice-board.md).', '')
  out.push('## How it is made', '')
  out.push('[README](README.md) says how to read the library in thirty seconds. The design is [ARCHITECTURE.md](ARCHITECTURE.md); the reading room\'s is [design/READING-ROOM.md](design/READING-ROOM.md). Everything here is generated from the repository by `build/library.mjs`; a thing not in the repository is not in the library.', '')
  return { files: { 'index.md': out.join('\n') } }
}
